import {readFile,writeFile} from 'node:fs/promises';
const source=await readFile(new URL('../supabase/migrations/202611260001_yougile_sync.sql',import.meta.url),'utf8');
const preflight=[
 '-- STAGING UPGRADE ONLY: apply once to the existing CRM, never rerun initial setup.',
 '-- Generated by scripts/build-yougile-upgrade.mjs. Contains no credentials or staff records.',
 'begin;',
 'do $$ begin',
 " if to_regclass('dvfm.employee_ids') is null or to_regclass('supabase_migrations.schema_migrations') is null then raise exception 'Existing CRM migrations required'; end if;",
 " if exists(select 1 from supabase_migrations.schema_migrations where version='202611260001') then raise exception 'YouGile migration already applied'; end if;",
 " if (select count(*) from supabase_migrations.schema_migrations where version in ('202611120001','202611120002'))<>2 then raise exception 'Both CRM migrations must be registered'; end if;",
 'end $$;',
 ''
].join('\n');
const sql=preflight+source.replace(/^begin;\n/m,'').replace(/commit;\s*$/,'')+
 "\ninsert into supabase_migrations.schema_migrations(version,name,statements) values ('202611260001','yougile_sync',array[]::text[]);\ncommit;\nselect 'yougile_schema_ready' as status, false as sync_enabled;\n";
const path=new URL('../docs/staging-upgrade-yougile.sql',import.meta.url);
if(process.argv.includes('--check')){
 if(await readFile(path,'utf8')!==sql)throw new Error('Rebuild staging-upgrade-yougile.sql');
}else await writeFile(path,sql);
